#include <stdio.h>
#include <string.h>

typedef enum { DATA, ACK } PacketType;

typedef struct { int src, dst; PacketType type; char payload[64]; int len; } Packet;

void send_packet(Packet *p) {
    printf("Packet: %d -> %d [%s] %s\n", p->src, p->dst, p->type==DATA?"DATA":"ACK", p->payload);
}

int main() {
    Packet p;
    p.src = 1; p.dst = 2; p.type = DATA;
    strcpy(p.payload, "Hello"); p.len = strlen(p.payload);
    send_packet(&p);
    return 0;
}
